const results = [];

for (const item of items) {
  // Change `output` if your AI response is stored in a different field
  let raw = item.json.output ?? item.json.text ?? item.json.response ?? item.json;

  // If the AI output is a JSON string, unwrap and parse it
  if (typeof raw === 'string') {
    raw = raw.trim();

    // Removes Markdown code fences if the AI used them
    raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');

    try {
      raw = JSON.parse(raw);
    } catch {
      // If raw text contains an array somewhere inside it
      const match = raw.match(/\[[\s\S]*\]/);
      if (!match) {
        results.push({
          json: { error: 'Could not find a valid JSON array', raw },
        });
        continue;
      }
      raw = JSON.parse(match[0]);
    }
  }

  const students = Array.isArray(raw) ? raw : [raw];

  for (const student of students) {
    const email =
      typeof student.Email === 'string' &&
      /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(student.Email)
        ? student.Email.trim().toLowerCase()
        : null;

    const phone =
      typeof student.Phone === 'string' &&
      student.Phone !== 'MISSING'
        ? student.Phone.replace(/\D/g, '')
        : null;

    results.push({
      json: {
        Student_ID: student.Student_ID?.trim() || null,
        Name: student.Name?.trim() || null,
        Email: email,
        Phone: phone,
        Course: student.Course?.trim() || null,
        Fee_Paid: Boolean(student.Fee_Paid),
        City: student.City?.trim() || null,
        Enrolled_Date: student.Enrolled_Date || null,

        // Flags help you route or review incomplete records
        needs_email_review: !email,
        needs_phone_review: !phone,
      },
    });
  }
}

return results;
